"""Publish the Windows reader pages and persistent storefront links."""
from pathlib import Path
import re, shutil, hashlib, json
ROOT=Path(__file__).resolve().parents[1]
APP=ROOT.parent/'unique-pdf-reader'
VERSION='1.9.1'
BASE=f'https://github.com/YSH0525/yooniquelabs-site/releases/download/pdf-reader-v{VERSION}/'

def build():
    home=(ROOT/'index.html').read_text(encoding='utf-8')
    nav=re.search(r'<header>.*?</header>',home,re.S)[0]
    footer='<footer><div class="wrap"><p>유니크랩스 · Yoonique Labs</p><a href="mailto:hello@yooniquelabs.kr">hello@yooniquelabs.kr</a> · <a href="/">홈</a> · <a href="/privacy.html">웹사이트 개인정보처리방침</a></div></footer>'
    style='''<style>.pdf-content{max-width:1000px;margin:auto;padding:40px 24px 72px}.pdf-content h1{font-size:clamp(32px,6vw,60px);line-height:1.15}.pdf-content h2{font-size:26px;margin:36px 0 16px}.pdf-content p,.pdf-content li{line-height:1.85}.pdf-content ul,.pdf-content ol{padding-left:24px}.pdf-content li{margin:12px 0}.pdf-content img{max-width:100%;height:auto;border-radius:16px;border:1px solid #dce4df}.pdf-content .downloads{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.pdf-content code{overflow-wrap:anywhere}.pdf-note{padding:20px;border-radius:14px;background:#edf3ee}.pdf-content section{padding:0;border:0;scroll-margin-top:90px}.pdf-content figure{margin:30px 0}.pdf-content figcaption{font-size:14px;color:#53685e}.pdf-content a:not(.btn){text-decoration:underline}</style>'''
    def page(path,title,description,body):
        dest=ROOT/path/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_text(f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | 유니크랩스</title><meta name="description" content="{description}"><link rel="canonical" href="https://yooniquelabs.kr/{path}/"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/showcase.css">{style}</head><body>{nav}<main class="pdf-content">{body}</main>{footer}</body></html>',encoding='utf-8')
    setup=f'Unique-PDF-Reader-Setup-{VERSION}.exe';portable=f'Unique-PDF-Reader-{VERSION}.exe';source=f'Unique-PDF-Reader-{VERSION}-source.zip'
    page('apps/pdf-reader','유니크 PDF Reader 다운로드','Windows용 PDF 읽기, 편집, 주석과 양식 입력. 설치 파일과 사용 방법을 확인하세요.',f'''<p class="eyebrow">WINDOWS · LOCAL PDF</p><h1>문서는 크게.<br>작업은 간편하게.</h1><p>유니크 PDF Reader로 PDF를 읽고, 필요한 내용을 고치고, 양식을 채우세요. 문서 처리는 내 컴퓨터에서 이루어지며 PDF를 서버에 업로드하지 않습니다.</p><p><strong>버전 {VERSION}</strong> · Windows 10/11 64비트 · 2026.10.29</p><div class="downloads"><a class="btn btn-primary" href="{BASE+setup}">Windows 설치 파일 다운로드 · 172 MiB</a><a class="btn" href="{BASE+portable}">포터블 다운로드 · 176 MiB</a></div><p><a href="/guides/pdf-reader/">설치부터 사용까지 안내 →</a> · <a href="#release">소스 코드·파일 검증</a></p><figure><img src="/assets/pdf-reader/screen.png" alt="좌측 메뉴와 페이지 구분선이 있는 유니크 PDF Reader 실제 화면" width="1633" height="974"><figcaption>실제 앱 화면 · 메뉴를 접으면 문서 영역이 더 넓어집니다.</figcaption></figure><h2>읽기부터 저장까지, 한 곳에서</h2><ul><li><strong>편안한 읽기:</strong> 너비 맞춤, 확대·축소, 검색, 목차와 개인 책갈피. 페이지 사이 간격과 경계선으로 구분합니다.</li><li><strong>편집과 주석:</strong> 본문 한 줄 교체, 텍스트·메모·형광펜, 페이지 회전·삭제·이동을 지원합니다.</li><li><strong>양식 입력:</strong> 입력란, 체크박스, 선택 항목을 채우고 PDF 사본으로 저장합니다. 지원되는 XFA 양식과 계산도 사용할 수 있습니다.</li><li><strong>빠른 열기:</strong> 문서 열기 버튼, 끌어놓기 또는 기본 앱 연결 후 PDF 더블클릭으로 열 수 있습니다.</li></ul><div class="pdf-note"><strong>다운로드 전에 확인하세요</strong><p>현재 배포 파일은 코드 서명되지 않아 Windows가 게시자를 확인할 수 없다는 경고를 표시할 수 있습니다. 이 페이지의 공식 다운로드와 아래 SHA-256을 확인하세요. macOS·모바일용 앱은 제공하지 않습니다.</p><p>OCR, 전자서명 생성, 모든 XFA/Adobe 스크립트와의 완전한 호환은 지원하지 않습니다. 중요한 문서는 사본을 저장한 뒤 결과를 확인하세요.</p></div><section id="release"><h2>1.9.1 변경 사항과 소스</h2><p>페이지 사이 12px 간격과 얇은 경계선을 추가했습니다. 좌측 메뉴와 넓은 문서 영역은 유지됩니다.</p><p>AGPL-3.0-or-later 오픈소스 · <a href="{BASE+source}">동일 버전 소스와 빌드 자료 다운로드 · 155 MiB</a></p><p><a href="{BASE}SHA256SUMS.txt">다운로드 파일 SHA-256 확인</a></p></section>''')
    page('guides/pdf-reader','유니크 PDF Reader 설치·사용 방법','Windows 설치, PDF 기본 앱 연결, 문서 열기, 주석 편집, 양식 입력과 사본 저장 방법.',f'''<p class="eyebrow">GET STARTED · {VERSION}</p><h1>설치부터 PDF 저장까지</h1><p><a href="/apps/pdf-reader/">다운로드 페이지로 이동 →</a></p><p><a href="#install">설치</a> · <a href="#open">문서 열기</a> · <a href="#read">읽기</a> · <a href="#edit">편집·주석</a> · <a href="#forms">양식</a> · <a href="#help">문제 해결</a></p><section id="install"><h2>1. 설치하고 기본 앱으로 연결하기</h2><ol><li>다운로드 페이지에서 <strong>Windows 설치 파일</strong>을 받습니다. Windows 10/11 64비트용입니다.</li><li><code>{setup}</code>를 실행하고 설치 위치를 선택해 설치를 완료합니다. 바탕화면이나 시작 메뉴의 <strong>유니크 PDF Reader</strong>로 실행하세요.</li><li>PDF 파일을 오른쪽 클릭 → <strong>연결 프로그램 → 다른 앱 선택</strong>에서 Unique PDF Reader를 선택하고 <strong>항상</strong>을 선택합니다. 목록에 없다면 다른 앱 찾기에서 설치 폴더의 <code>Unique PDF Reader.exe</code>를 지정하세요. Windows 버전에 따라 항목 이름이 다를 수 있습니다.</li><li>이후 PDF를 더블클릭하면 해당 문서가 바로 열립니다. 앱이 이미 실행 중이면 기존 창에서 열립니다.</li></ol><p>설치를 원하지 않으면 포터블 파일을 실행하세요. 별도 Python 설치는 필요하지 않습니다. 업데이트할 때는 작업한 문서를 저장하고 앱을 종료한 후 새 설치 파일을 실행하세요.</p><p class="pdf-note">코드 서명이 없어 게시자 확인 경고가 나타날 수 있습니다. 공식 배포 주소와 파일 해시를 확인하고 실행 여부를 결정하세요. 보안 프로그램을 끄지 마세요.</p></section><section id="open"><h2>2. 문서 열기</h2><p>왼쪽의 <strong>+ 문서 열기</strong> 또는 <strong>Ctrl+O</strong>를 누르면 Windows 파일 선택 창이 열립니다. 폴더에서 PDF를 골라 여세요. 탐색기에서 PDF를 앱으로 끌어놓아도 됩니다. + 버튼은 빈 PDF 생성이 아니라 기존 문서 열기 버튼입니다.</p><p>암호가 있는 PDF는 암호를 입력합니다. 입력 파일 크기는 최대 300MB입니다. 처음에는 홈의 샘플 PDF로 기능을 익혀보세요.</p></section><section id="read"><h2>3. 크게 읽고 빠르게 찾기</h2><ul><li>왼쪽 아래에서 페이지 번호를 입력하거나 이전·다음 화살표로 이동합니다.</li><li>확대 메뉴의 <strong>너비 맞춤</strong> 또는 <strong>페이지 맞춤</strong>을 선택합니다. 왼쪽 아래 접기 화살표를 누르면 메뉴가 접혀 문서가 더 넓어집니다.</li><li><strong>Ctrl+F</strong>로 본문을 검색합니다. Enter는 다음 결과, Shift+Enter는 이전 결과입니다. 이미지로만 된 스캔 PDF는 OCR이 없으므로 검색할 수 없습니다.</li><li>목차와 책갈피로 자주 보는 위치에 이동합니다. 개인 책갈피와 최근 문서 위치는 이 컴퓨터에 저장되며 PDF 파일에 삽입되지 않습니다.</li></ul></section><section id="edit"><h2>4. 편집·주석 후 사본 저장하기</h2><ol><li><strong>편집 · 주석</strong>을 열고 본문 목록에서 한 줄을 선택해 교체하거나 형광펜을 적용합니다.</li><li>텍스트나 메모 내용을 입력하고 배치 버튼을 누른 뒤 PDF 위의 원하는 위치를 클릭합니다. 기존 메모는 주석 목록에서 수정·삭제합니다.</li><li>필요하면 페이지를 회전·삭제·이동합니다. 잘못 수정했다면 되돌리기를 사용하세요.</li><li><strong>사본 저장</strong>으로 다른 파일명에 저장한 다음 다시 열어 결과를 확인합니다. 원본 경로에는 덮어쓰지 않습니다.</li></ol><p>본문 교체는 원래 글꼴·자동 문단 배치를 그대로 보존하지 않습니다. 서명된 문서와 편집 제한 문서는 수정이 제한될 수 있습니다. <strong>Ctrl+P</strong>로 인쇄할 수 있으며 페이지를 이미지로 출력합니다.</p></section><section id="forms"><h2>5. 양식 입력·자동 계산·저장하기</h2><ol><li>입력 가능한 PDF를 열고 <strong>양식 입력</strong>을 누릅니다.</li><li>현재 페이지의 입력란, 체크박스, 라디오 버튼과 선택 목록을 채웁니다.</li><li><strong>입력 적용</strong>으로 문서에 반영합니다. 지원되는 계산은 적용 또는 저장할 때 갱신됩니다.</li><li>반복 행이 있는 지원 양식에서는 입력을 먼저 적용한 뒤 행을 추가·삭제합니다.</li><li><strong>양식 PDF 저장</strong>으로 사본을 저장하고, 저장한 PDF를 다시 열어 입력값과 계산 결과를 확인합니다.</li></ol><p>홈의 양식 샘플과 XFA 계산 샘플로 연습할 수 있습니다. XFA와 스크립트는 지원되는 문법·구조 범위에서 동작합니다. 지원하지 않는 계산 안내가 나오면 결과를 완전하다고 간주하지 말고 원래 양식 제작자가 권장하는 앱에서 확인하세요.</p></section><section id="help"><h2>자주 묻는 질문</h2><h3>더블클릭했는데 다른 앱이 열려요.</h3><p>Windows 설정 → 앱 → 기본 앱에서 .pdf의 기본 앱을 유니크 PDF Reader로 선택하세요.</p><h3>PDF 안의 여백도 없앨 수 있나요?</h3><p>앱의 불필요한 상하 여백은 줄였지만 PDF 원본 안의 흰 여백은 문서의 일부입니다. 너비 맞춤이나 확대를 이용하세요.</p><h3>저장한 내용이 보이지 않아요.</h3><p>입력 적용 후 저장했는지, 원본이 아니라 방금 저장한 사본을 열었는지 확인하세요. 지원하지 않는 양식·스크립트는 안내 메시지를 확인하세요.</p><h3>문의는 어디로 하나요?</h3><p><a href="mailto:hello@yooniquelabs.kr">hello@yooniquelabs.kr</a>로 앱 버전, Windows 버전, 문제 상황을 알려주세요. 개인정보가 포함된 PDF 대신 재현 가능한 샘플을 이용해 주세요.</p></section>''')
    banner='<section id="windows-download"><div class="wrap"><p class="eyebrow">FOR WINDOWS</p><h2>유니크 PDF Reader</h2><p>내 컴퓨터에서 PDF 읽기·편집·주석·양식 입력까지.</p><div class="cta"><a class="btn btn-primary" href="/apps/pdf-reader/">Windows 다운로드 →</a><a class="btn" href="/guides/pdf-reader/">설치·사용 방법</a></div></div></section>'
    home=re.sub(r'<section id="windows-download">.*?</section>','',home,flags=re.S)
    home=home.replace('<section id="apps"',banner+'\n<section id="apps"',1)
    (ROOT/'index.html').write_text(home,encoding='utf-8')
    g=ROOT/'guides/index.html';text=g.read_text(encoding='utf-8')
    if '/guides/pdf-reader/' not in text:text=text.replace('<div class="wrap grid">','<div class="wrap grid"><article class="card"><span class="tag">Windows · 유니크 PDF Reader</span><h2><a href="/guides/pdf-reader/">PDF Reader 설치와 사용 방법</a></h2><p>다운로드, 기본 앱 연결, 편집·주석과 양식 저장까지 안내합니다.</p></article>',1)
    g.write_text(text,encoding='utf-8')
    sm=ROOT/'sitemap.xml';text=sm.read_text(encoding='utf-8')
    for route in ['apps/pdf-reader','guides/pdf-reader']:
        url=f'https://yooniquelabs.kr/{route}/'
        if url not in text:text=text.replace('</urlset>',f'<url><loc>{url}</loc><lastmod>2026-10-29</lastmod></url></urlset>')
    sm.write_text(text,encoding='utf-8')

if __name__=='__main__':build()
